Schema.DescribeSObjectResult accountDescribe = Account.SObjectType.getDescribe();
Schema.DescribeFieldResult nameDescribe = Account.Name.getDescribe();
Boolean describeOk = accountDescribe.getLabelPlural() == 'Accounts' && accountDescribe.isAccessible() && accountDescribe.isCreateable() && accountDescribe.isDeletable() && accountDescribe.isQueryable() && accountDescribe.isSearchable() && accountDescribe.isUndeletable() && accountDescribe.isUpdateable() && nameDescribe.getLength() == 255 && nameDescribe.getType() == Schema.DisplayType.STRING && nameDescribe.isAccessible() && nameDescribe.isCreateable() && nameDescribe.isNameField() && nameDescribe.isUpdateable();
Account record = new Account(Name = 'CB185 before update');
Database.insert(record);
record.Name = 'CB185 after update';
Database.update(record);
Account queried = [SELECT Name FROM Account WHERE Id = :record.Id];
Boolean dmlOk = record.Id != null && queried.Name == 'CB185 after update';
Database.delete(record);
System.debug(describeOk && dmlOk);

